import { afterEach, describe, expect, mock, test } from "bun:test";
import { createInputController, type InputController } from "@/lib/game/input/inputController";
import type { GameEngine } from "@/lib/game/engine/GameEngine";
import type { Command } from "@/lib/game/engine/commands";

/**
 * A minimal stand-in for the engine: the input controller only reaches for
 * `state` flags and `dispatch`/`applyLook` on the keydown paths we exercise.
 */
function makeStubEngine() {
  const dispatch = mock((_command: Command) => {});
  const engine = {
    state: { paused: false, inventoryOpen: false, isDead: false },
    dispatch,
    applyLook: () => {}
  } as unknown as GameEngine;
  return { engine, dispatch };
}

function pressKey(code: string, modifiers: { shiftKey?: boolean } = {}): void {
  document.dispatchEvent(new KeyboardEvent("keydown", { code, bubbles: true, ...modifiers }));
}

let controller: InputController | null = null;

afterEach(() => {
  controller?.dispose();
  controller = null;
});

describe("inputController emergency unstuck", () => {
  function setup() {
    const { engine, dispatch } = makeStubEngine();
    controller = createInputController({
      canvas: document.createElement("canvas"),
      engine,
      onResize: () => {},
      onLockChange: () => {}
    });
    return dispatch;
  }

  test("a bare U keypress does not trigger unstuck", () => {
    const dispatch = setup();
    pressKey("KeyU");
    expect(dispatch).not.toHaveBeenCalledWith({ type: "unstuck" });
  });

  test("Shift + U triggers unstuck", () => {
    const dispatch = setup();
    pressKey("KeyU", { shiftKey: true });
    expect(dispatch).toHaveBeenCalledWith({ type: "unstuck" });
  });
});

import ItemIcon from "@/components/game/ItemIcon";
import { itemTooltipFor, useItemTooltip } from "@/components/game/ItemTooltip";
import type { InventorySlot } from "@/lib/game/types";

type HotbarProps = {
  inventory: InventorySlot[];
  selectedSlot: number;
  hotbarSlots: number;
  onSelectSlot: (index: number) => void;
};

/**
 * The Minecraft hotbar: 9 dark translucent slots with a white outline on the
 * selection and the selected item's name fading in above the bar. The name is
 * keyed on the selection so every change remounts it and replays the CSS
 * fade-in/fade-out animation — no timers or state.
 */
export default function Hotbar({ inventory, selectedSlot, hotbarSlots, onSelectSlot }: HotbarProps) {
  const visible = inventory.slice(0, hotbarSlots);
  const selected = visible[selectedSlot];
  const selectedLabel = selected?.id && selected.count > 0 ? selected.label : "";
  const { tooltip, bind } = useItemTooltip();

  return (
    <div className="hotbar-area">
      {selectedLabel && (
        <div key={`${selectedSlot}:${selectedLabel}`} className="hotbar-item-name">
          {selectedLabel}
        </div>
      )}
      <div className="hotbar" data-testid="hotbar">
        {visible.map((slot, idx) => (
          <button
            key={`hotbar-${idx}`}
            className={idx === selectedSlot ? "hotbar-slot active" : "hotbar-slot"}
            onClick={() => onSelectSlot(idx)}
            aria-label={slot.id && slot.count > 0 ? `Slot ${idx + 1}: ${slot.label}` : `Slot ${idx + 1}: empty`}
            {...bind(itemTooltipFor(slot))}
          >
            <ItemIcon slot={slot} size={32} />
          </button>
        ))}
      </div>
      {tooltip}
    </div>
  );
}

import PixelImg from "@/components/game/PixelImg";
import { hudIconUrl } from "@/lib/ui/sprites";

type StatusBarsProps = {
  hearts: number;
  maxHearts: number;
  hunger: number;
  maxHunger: number;
  armorPoints: number;
};

const ICON_SIZE = 18;

type IconKind = "heart" | "hunger" | "armor";

/** Icon states for a 10-icon Minecraft bar: each icon covers 2 points. */
export function iconStates(value: number, max: number): Array<"full" | "half" | "container"> {
  const icons = Math.ceil(max / 2);
  return Array.from({ length: icons }, (_, i) => {
    if (value >= i * 2 + 2) return "full";
    if (value === i * 2 + 1) return "half";
    return "container";
  });
}

function IconRow({ kind, value, max, label, reversed }: { kind: IconKind; value: number; max: number; label: string; reversed?: boolean }) {
  const states = iconStates(value, max);
  return (
    <div
      className={reversed ? "status-icon-row reversed" : "status-icon-row"}
      role="meter"
      aria-label={`${label}: ${value}/${max}`}
      aria-valuenow={value}
      aria-valuemin={0}
      aria-valuemax={max}
    >
      {states.map((state, i) => (
        <span key={`${kind}-${i}`} data-icon={`${kind}_${state}`}>
          <PixelImg src={hudIconUrl(`${kind}_${state}`)} alt="" size={ICON_SIZE} aria-hidden />
        </span>
      ))}
    </div>
  );
}

/**
 * The Minecraft status rows above the hotbar: hearts on the left, hunger on
 * the right (filling right-to-left), and an armor row over the hearts that
 * only appears once something is equipped.
 */
export default function StatusBars({ hearts, maxHearts, hunger, maxHunger, armorPoints }: StatusBarsProps) {
  return (
    <div className="status-bars">
      <div className="status-bars-left">
        {armorPoints > 0 && <IconRow kind="armor" value={armorPoints} max={20} label="Armor" />}
        <IconRow kind="heart" value={Math.max(0, Math.round(hearts))} max={maxHearts} label="Health" />
      </div>
      <div className="status-bars-right">
        <IconRow kind="hunger" value={Math.max(0, Math.round(hunger))} max={maxHunger} label="Hunger" reversed />
      </div>
    </div>
  );
}

